window.addEventListener("DOMContentLoaded",()=>{document.querySelectorAll('a[href^="tel:"], a[href^="mailto:"]').forEach(t=>{t.addEventListener("click",()=>{if(typeof window.gtag!="function")return;const e=t.getAttribute("href")||"",n=e.startsWith("tel:")?"phone_click":"email_click";window.gtag("event",n,{link_url:e,page_path:window.location.pathname,page_title:document.title})})})});
